// unit-test.lib.civet

type AutoPromise<T> = Promise<Awaited<T>>;
import {assert, assertEquals} from '@std/assert'

import {justThrow, croak} from 'croak'
import {
	undef, sleep, defined, notdefined,
	} from 'base-utils'
import {TIterator, TAsyncIterator, TVoidFunc, hash} from 'datatypes'

let nextNum = 0

// ---------------------------------------------------------------------------

export const getTestName = (
		name: (string | undefined) = undef
		): string => {

	if (name === undefined) {
		nextNum += 1
		return `test ${nextNum}`
	}
	else {
		return name
	}
}

// ---------------------------------------------------------------------------

export const equal = (
		value: unknown,
		expected: unknown,
		testName: (string | undefined) = undef
		): void => {

	const name = getTestName(testName)
	Deno.test(name, () => assertEquals(value, expected))
	return
}

// ---------------------------------------------------------------------------

export const truthy = (
	value: unknown,
	testName: (string | undefined) = undef
	): void => {

	const name = getTestName(testName)
	Deno.test(name, () => assert(value))
	return
}

// ---------------------------------------------------------------------------

export const falsy = (
	value: unknown,
	testName: (string | undefined) = undef
	): void => {

	const name = getTestName(testName)
	Deno.test(name, () => assert((!value)))
	return
}

// ---------------------------------------------------------------------------

export const succeeds = (
	func: TVoidFunc,
	testName: (string | undefined) = undef
	): void => {

	const name = getTestName(testName)
	Deno.test(name, async (): AutoPromise<void> => {
		await func()
	})
	return
}

// ---------------------------------------------------------------------------

export const fails = (
	func: TVoidFunc,
	testName: (string | undefined) = undef
	): void => {

	const name = getTestName(testName)
	Deno.test(name, (): void => {
		justThrow(true)
		try {
			func()
			croak("in fails() but function succeeded")
		}
		catch (err) {}
		finally {
			justThrow(false)
		}
	})
	return
}

// ---------------------------------------------------------------------------
// ASYNC

export const generates = <TOut,>(
		value: TIterator<TOut>,
		expected: unknown,
		testName: (string | undefined) = undef
		): void => {

	const lItems = [...value]
	const name = getTestName(testName)
	Deno.test(name, () => assertEquals(lItems, expected))
	return
}

// ---------------------------------------------------------------------------
// ASYNC

export const generatesAsync = async <TOut,>(
		value: TAsyncIterator<TOut>,
		expected: unknown,
		testName: (string | undefined) = undef
		): AutoPromise<void> => {

	const lItems = await Array.fromAsync(value)
	const name = getTestName(testName)
	Deno.test(name, () => assertEquals(lItems, expected))
	return
}

